  `panelStates` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '[ [ 0, 0, 0, 0, 0, 0 ] ]' CHECK (json_valid(`panelStates`)),
  `plate` varchar(8) DEFAULT NULL,
