  `vehradio.station` int(11) NOT NULL DEFAULT 1,
  `batteryCharge` float NOT NULL DEFAULT 2048,
  `maxBatteryCharge` float NOT NULL DEFAULT 2048,
  `batteryRate` float NOT NULL DEFAULT 0,
  `variant` text NOT NULL DEFAULT '[ [ ] ]',
  `winterTires` int(11) NOT NULL DEFAULT 0,
